import playersJson from './players.json'
import teamsJson from './teams.json'
import type { Player, Team } from './types'

// The JSON is generated by `npm run data` and checked by data.test.ts, so the casts are safe.
export const players = playersJson as Player[]
export const teams = teamsJson as Team[]

export const teamById = new Map(teams.map((t) => [t.id, t]))
export const playersByTeam = (teamId: string) => players.filter((p) => p.teamId === teamId)

export * from './names'
export * from './types'
